<template>
  <Card class="w-full" :class="statusStyle.card">
    <CardHeader>
      <CardTitle>
        <InlineEntityUser :user="referral.user" :user-id="referral.user.id" />
      </CardTitle>
    </CardHeader>
    <CardContent class="grid grid-cols-4 gap-2 justify-items-stretch place-items-center">
      <div
        class="col-span-1 md:col-span-2 font-semibold md:text-xl"
        :class="{
          'line-through decoration-2 text-muted-foreground': referral.challenge.status === 'expired',
        }"
      >
        ${{ reward }}
      </div>

      <div class="col-span-3 md:col-span-2 justify-self-end md:text-nowrap text-sm md:text-base">
        <template v-if="referral.challenge.status === 'active'">
          <div>expires in {{ expireInDays }} days</div>
        </template>
        <template v-else-if="referral.challenge.status === 'completed'">
          <InlineEntityEarning v-if="referral.challenge.earning_id" :earning-id="referral.challenge.earning_id" />
          <span v-else class="italic">Processing payment</span>
        </template>
        <span v-if="referral.challenge.status === 'expired'"
          >expired on {{ formatDateTzToFormat(referral.challenge.expire_at, 'MM/dd/yyyy', timezone) }}</span
        >
      </div>

      <div v-if="referral.challenge.status === 'active'" class="flex flex-col items-center gap-1 col-span-4">
        <Progress :model-value="referral.challenge.progress_perc * 100" />
        <div class="flex-none size-fit">
          <p class="text-center text-xs md:text-sm md:text-nowrap">
            {{ referral.challenge.doors_left }} doors or {{ referral.challenge.signatures_left }} signatures left
          </p>
        </div>
      </div>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { differenceInCalendarDays } from 'date-fns';
import { type ReferralInfo } from '~/client';

const { timezone } = useUserRole();

interface Props {
  referral: ReferralInfo;
}

const props = defineProps<Props>();

const statusCardStyles: Record<string, string> = {
  active: 'bg-blue-50',
  completed: 'bg-green-50',
  expired: 'bg-gray-50',
};

const statusStyle = computed(() => ({
  card: statusCardStyles[props.referral.challenge.status] ?? '',
}));

const reward = computed(() =>
  props.referral.challenge.reward % 1 ? props.referral.challenge.reward.toFixed(2) : props.referral.challenge.reward
);

const expireInDays = computed(() =>
  Math.max(differenceInCalendarDays(props.referral.challenge.expire_at, new Date()), 0)
);
</script>
