<template>
  <Skeleton v-if="isLoading" class="h-3 w-20 inline-block" />
  <NuxtLink
    v-else-if="paidDate"
    :to="{ name: 'earnings-id', params: { id: earningId } }"
    class="underline underline-offset-2"
  >
    paid on {{ paidDate }}
  </NuxtLink>
  <span v-else>payment not found</span>
</template>
<script setup lang="ts">
import { getEarningShortInfo } from '~/client';
import { formatDateTzToFormat } from '~/utils/formatDateToFormat';

const props = defineProps<{
  label?: string;
  earningId: string;
}>();

const { data, isLoading, error } = useQuery({
  key: () => ['earning.short-info', props.earningId],
  query: () => getEarningShortInfo({ composable: '$fetch', path: { earning_id: props.earningId } }),
  enabled: () => !!props.earningId,
});

const { timezone } = useUserRole();

const paidDate = computed(() =>
  data.value ? formatDateTzToFormat(data.value?.created_at, 'MM/dd/yyyy', timezone.value) : undefined
);
</script>
